#include "oblivion/settings.hpp"
#include <Windows.h>
#include <algorithm>
namespace oblivion { namespace { constexpr wchar_t key_name[]=L"Software\\Oblivion"; bool rd(HKEY k,const wchar_t*n,DWORD&v){DWORD t=0,s=sizeof(v);return RegQueryValueExW(k,n,nullptr,&t,reinterpret_cast<BYTE*>(&v),&s)==ERROR_SUCCESS&&t==REG_DWORD;} bool wr(HKEY k,const wchar_t*n,DWORD v){return RegSetValueExW(k,n,0,REG_DWORD,reinterpret_cast<const BYTE*>(&v),sizeof(v))==ERROR_SUCCESS;} }
erase_options load_default_erase_options(){erase_options o;HKEY k=nullptr;if(RegOpenKeyExW(HKEY_CURRENT_USER,key_name,0,KEY_QUERY_VALUE,&k)!=ERROR_SUCCESS)return o;DWORD v=0;if(rd(k,L"EraseMode",v)&&v<=static_cast<DWORD>(erase_mode::gutmann))o.mode=static_cast<erase_mode>(v);if(rd(k,L"Verify",v))o.verify=v!=0;if(rd(k,L"EraseAlternateStreams",v))o.erase_alternate_streams=v!=0;if(rd(k,L"RenameBeforeDelete",v))o.rename_before_delete=v!=0;if(rd(k,L"RenameRounds",v))o.rename_rounds=static_cast<unsigned>((std::min)(v,DWORD{32}));if(rd(k,L"HardlinkPolicy",v)&&v==static_cast<DWORD>(hardlink_policy::delete_link_only))o.hardlinks=hardlink_policy::delete_link_only;RegCloseKey(k);return o;}
bool save_default_erase_options(const erase_options&o){HKEY k=nullptr;if(RegCreateKeyExW(HKEY_CURRENT_USER,key_name,0,nullptr,0,KEY_SET_VALUE,nullptr,&k,nullptr)!=ERROR_SUCCESS)return false;auto hp=o.hardlinks==hardlink_policy::delete_link_only?hardlink_policy::delete_link_only:hardlink_policy::block;bool ok=wr(k,L"EraseMode",static_cast<DWORD>(o.mode))&&wr(k,L"Verify",o.verify)&&wr(k,L"EraseAlternateStreams",o.erase_alternate_streams)&&wr(k,L"RenameBeforeDelete",o.rename_before_delete)&&wr(k,L"RenameRounds",static_cast<DWORD>((std::min)(o.rename_rounds,32u)))&&wr(k,L"HardlinkPolicy",static_cast<DWORD>(hp));RegCloseKey(k);return ok;}
bool reset_default_erase_options(){LONG r=RegDeleteTreeW(HKEY_CURRENT_USER,key_name);return r==ERROR_SUCCESS||r==ERROR_FILE_NOT_FOUND;}
}
